{
  "propositions": [
    {
      "id": "P1",
      "proposition": "Section 49-3-103(d)(3) is amended to add \"or public charter school\" after \"Explain how an LEA\".",
      "importance": "core",
      "section": "SECTION 1",
      "source_quote": "adding the language \"or public charter school\" after the language \"Explain how an LEA\"."
    },
    {
      "id": "P2",
      "proposition": "Under replacement § 49-3-105(d), the department must administer and allocate student-generated funding under that section to the student's LEA for the duration of membership, except that funding generated under subdivision (c)(3) must remain with the department and the state share generated by public charter school students must go directly to their charter schools.",
      "importance": "core",
      "section": "SECTION 2",
      "source_quote": "must not be allocated to the LEA, but must be allocated directly to the public charter school."
    },
    {
      "id": "P3",
      "proposition": "For funding purposes, a student's LEA membership runs from the first through the last day of membership, but an early graduate's membership extends to the student's expected graduation date.",
      "importance": "supporting",
      "section": "SECTION 2",
      "source_quote": "the membership of a student who graduates early is extended to the student's expected graduation date for funding purposes."
    },
    {
      "id": "P4",
      "proposition": "Section 49-3-316(c) is amended to add \"or public charter school\" after every occurrence of \"LEA\".",
      "importance": "supporting",
      "section": "SECTION 3",
      "source_quote": "language \"or public charter school\" after the language \"LEA\" wherever it appears in subsection (c)"
    },
    {
      "id": "P5",
      "proposition": "The commissioner, in consultation with the comptroller of the treasury, must develop, revise as necessary, and prescribe a standardized financial accounting and reporting system for all public charter schools, including appropriate forms or documentation. The system must facilitate year-to-year and agency-to-agency comparisons and adequately indicate each charter school's sources and uses of all funds.",
      "importance": "core",
      "section": "SECTION 3",
      "source_quote": "prescribe a standardized system of financial accounting and reporting for all public charter schools"
    },
    {
      "id": "P6",
      "proposition": "The commissioner must review fiscal public school records in all public charter schools to ensure that expenditures for current operation and maintenance, capital outlay, and other school purposes are properly accounted for and safeguarded.",
      "importance": "supporting",
      "section": "SECTION 3",
      "source_quote": "The commissioner shall review the fiscal public school records in all public charter schools"
    },
    {
      "id": "P7",
      "proposition": "The commissioner may require public charter schools receiving state education funding under Title 49, Chapter 3, Part 1 or otherwise to comply with one or more requirements imposed on LEAs by § 49-3-316, as the commissioner deems appropriate or applicable.",
      "importance": "core",
      "section": "SECTION 3",
      "source_quote": "comply with one (1) or more of the requirements established for LEAs in this section, as the commissioner deems appropriate or applicable."
    },
    {
      "id": "P8",
      "proposition": "Under replacement § 49-13-112(a), a local board of education must allocate to a public charter school the local student-generated funds for its prior-year member students in alignment with TISA under Title 49, Chapter 3, Part 1.",
      "importance": "core",
      "section": "SECTION 4",
      "source_quote": "The local student-generated funds for member students in the public charter school for the prior year"
    },
    {
      "id": "P9",
      "proposition": "The local board must also allocate to the charter school, for each prior-year member student, the district's current-year average per-pupil state and local funds above those required by TISA.",
      "importance": "supporting",
      "section": "SECTION 4",
      "source_quote": "The average per pupil state and local funds received by the district in the current school year above those required by the TISA"
    },
    {
      "id": "P10",
      "proposition": "The local board must also allocate the per-student state and local funds received by the LEA for current-year charter school member students beyond the prior year's membership.",
      "importance": "supporting",
      "section": "SECTION 4",
      "source_quote": "The per student state and local funds received by the LEA for member students in the public charter school in the current school year beyond the prior year's membership"
    },
    {
      "id": "P11",
      "proposition": "The local board must also allocate to the charter school all appropriate allocations under federal law or regulation, including IDEA and ESEA funds.",
      "importance": "supporting",
      "section": "SECTION 4",
      "source_quote": "All appropriate allocations under federal law or regulation, including, but not limited to, IDEA and ESEA funds."
    },
    {
      "id": "P12",
      "proposition": "The department of education must allocate directly to each public charter school an amount equal to the state student-generated funds for its prior-year member students in alignment with TISA under Title 49, Chapter 3, Part 1.",
      "importance": "core",
      "section": "SECTION 4",
      "source_quote": "The department of education shall allocate directly to the public charter school an amount equal to the state student-generated funds"
    },
    {
      "id": "P13",
      "proposition": "An LEA must disburse federal funds it receives to charter schools it authorizes through either joint agreements on shared services by individual charter schools or sub-grants for a charter school's equitable share of the federal grant based on eligible students. Allocations must follow department of education policies and procedures.",
      "importance": "core",
      "section": "SECTION 4",
      "source_quote": "either joint agreement on shared services by individual public charter schools or sub-grants to a public charter school"
    },
    {
      "id": "P14",
      "proposition": "Each LEA must include in its budget submitted under § 49-2-203 the per-pupil local money it will pass through to charter schools in the upcoming school year, including all calculations listed in § 49-13-112. That year's charter school allocations must be based on those calculated amounts.",
      "importance": "supporting",
      "section": "SECTION 4",
      "source_quote": "Allocations to public charter schools during that year must be based on the calculated amounts."
    },
    {
      "id": "P15",
      "proposition": "Each LEA must distribute the portion of local funds it expects to receive to public charter schools in at least nine equal installments, in the same manner as state funds are distributed under Title 49, Chapter 3.",
      "importance": "core",
      "section": "SECTION 4",
      "source_quote": "in no fewer than nine (9) equal installments to public charter schools"
    },
    {
      "id": "P16",
      "proposition": "Each LEA must adjust local payments to charter schools at least in October, February, and June based on changes in revenue, student membership, or student services.",
      "importance": "supporting",
      "section": "SECTION 4",
      "source_quote": "at a minimum, in October, February, and June, based on changes in revenue, student membership, or student services."
    },
    {
      "id": "P17",
      "proposition": "Public charter schools must spend all funds received according to the submitted budget or revisions made by the charter school's governing body, subject to state and federal law.",
      "importance": "supporting",
      "section": "SECTION 4",
      "source_quote": "All funds received by a public charter school must be spent according to the budget submitted or as otherwise revised by the public charter school governing body"
    },
    {
      "id": "P18",
      "proposition": "Sections 1 and 3 take effect upon becoming law. Sections 2 and 4 take effect upon becoming law for rulemaking purposes and on July 1, 2025, for all other purposes.",
      "importance": "supporting",
      "section": "SECTION 5",
      "source_quote": "For all other purposes, Sections 2 and 4 of this act take effect July 1, 2025, the public welfare requiring it."
    }
  ]
}
